(function(){'use strict';const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,el=k=>document.getElementById('M32-'+k);if(!el('plot'))return;
const defaults={qx:1,qy:0,mask:true},keys=[[1,0],[0,1],[-1,0],[0,-1]],values=[[2,0],[0,4],[-2,0],[0,-4]],colors=['#0072B2','#D58500','#74569d','#6c8e3f'];let p={...defaults},drag=false;
function state(){const scores=keys.map(k=>(p.qx*k[0]+p.qy*k[1])/Math.sqrt(2)),valid=keys.map((_,i)=>!p.mask||i<2),max=Math.max(...scores.filter((_,i)=>valid[i])),exp=scores.map((v,i)=>valid[i]?Math.exp(v-max):0),sum=exp.reduce((a,b)=>a+b,0),weights=exp.map(v=>v/sum);return {...p,scores,weights,valid,outX:weights.reduce((a,w,i)=>a+w*values[i][0],0),outY:weights.reduce((a,w,i)=>a+w*values[i][1],0)};}
function draw(){const s=state();for(const k of ['qx','qy']){el(k).value=p[k];el(k+'-value').textContent=p[k].toFixed(2);}el('mask').checked=p.mask;
 let h='<defs><marker id="M32-arrow" markerUnits="userSpaceOnUse" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10" fill="context-stroke"/></marker></defs>';
 h+=`<text x="155" y="30" text-anchor="middle" fill="currentColor">${tr('查询与键方向','Query and key directions')}</text><text x="420" y="30" text-anchor="middle" fill="currentColor">${tr('读取权重','Reading weights')}</text><text x="710" y="30" text-anchor="middle" fill="currentColor">${tr('值与加权输出','Values and weighted output')}</text>`;
 for(const v of [-2,-1,0,1,2])h+=`<line x1="${155+v*50}" y1="110" x2="${155+v*50}" y2="310" stroke="#e1e7ea"/><line x1="55" y1="${210-v*50}" x2="255" y2="${210-v*50}" stroke="#e1e7ea"/><text x="${155+v*50}" y="333" text-anchor="middle" fill="currentColor" font-size="12">${v}</text>`;
 for(let i=0;i<4;i++){const k=keys[i],v=values[i],opacity=s.valid[i]?1:.2;h+=`<circle cx="${155+k[0]*50}" cy="${210-k[1]*50}" r="5" fill="${colors[i]}"/><text x="${155+k[0]*70}" y="${215-k[1]*70}" text-anchor="middle" fill="${colors[i]}" font-size="14">K${i+1}</text><text x="330" y="${105+i*65}" fill="currentColor">K${i+1}</text><rect x="370" y="${88+i*65}" width="145" height="22" fill="#e7edef"/><rect x="370" y="${88+i*65}" width="${145*s.weights[i]}" height="22" fill="${s.valid[i]?colors[i]:'#bdc8ce'}"/><text x="520" y="${105+i*65}" fill="currentColor" font-size="13">${s.weights[i].toFixed(3)}</text><line x1="710" y1="230" x2="${710+v[0]*35}" y2="${230-v[1]*35}" stroke="${colors[i]}" stroke-width="2.5" opacity="${opacity}" marker-end="url(#M32-arrow)"/><text x="${710+v[0]*42}" y="${235-v[1]*39}" text-anchor="middle" fill="${colors[i]}" opacity="${opacity}" font-size="14">V${i+1}</text>`;}
 h+=`<line x1="155" y1="210" x2="${155+p.qx*50}" y2="${210-p.qy*50}" stroke="#203e4a" stroke-width="4" marker-end="url(#M32-arrow)"/><circle cx="${155+p.qx*50}" cy="${210-p.qy*50}" r="7" fill="#203e4a"/><line x1="710" y1="230" x2="${710+s.outX*35}" y2="${230-s.outY*35}" stroke="#008675" stroke-width="5" marker-end="url(#M32-arrow)"/><circle cx="${710+s.outX*35}" cy="${230-s.outY*35}" r="5" fill="#008675"/><text x="155" y="365" text-anchor="middle" fill="currentColor">q=(${p.qx.toFixed(2)},${p.qy.toFixed(2)})</text><text x="710" y="410" text-anchor="middle" fill="currentColor">O=(${s.outX.toFixed(3)},${s.outY.toFixed(3)})</text>`;el('plot').innerHTML=h;
 el('result').textContent=tr(`权重之和=${s.weights.reduce((a,b)=>a+b,0).toFixed(6)}；输出=(${s.outX.toFixed(6)},${s.outY.toFixed(6)})。${p.mask?'位置2、3被遮罩。':'四个位置均可读取。'}`,`Weight sum=${s.weights.reduce((a,b)=>a+b,0).toFixed(6)}; output=(${s.outX.toFixed(6)},${s.outY.toFixed(6)}). ${p.mask?'Positions2 and3 are masked.':'All four positions are readable.'}`);}
function set(v){for(const k of ['qx','qy'])if(Number.isFinite(Number(v[k])))p[k]=Math.max(-2,Math.min(2,+v[k]));if(typeof v.mask==='boolean')p.mask=v.mask;draw();return state();}function reset(){p={...defaults};draw();return state();}
for(const k of ['qx','qy'])el(k).addEventListener('input',()=>set({[k]:+el(k).value}));el('mask').addEventListener('change',()=>set({mask:el('mask').checked}));el('reset').addEventListener('click',reset);
function point(e){const svg=el('plot'),pnt=svg.createSVGPoint();pnt.x=e.clientX;pnt.y=e.clientY;return pnt.matrixTransform(svg.getScreenCTM().inverse());}
el('plot').addEventListener('pointerdown',e=>{const t=point(e);if(t.x<285&&t.x>25&&t.y>70&&t.y<345){drag=true;el('plot').setPointerCapture(e.pointerId);set({qx:(t.x-155)/50,qy:(210-t.y)/50});}});el('plot').addEventListener('pointermove',e=>{if(drag){const t=point(e);set({qx:(t.x-155)/50,qy:(210-t.y)/50});}});el('plot').addEventListener('pointerup',()=>{drag=false;});el('plot').addEventListener('pointercancel',()=>{drag=false;});window.CourseLab={state,set,reset};draw();})();
